import React, { useState, useEffect, useRef } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const NhanTin = () => {
    const [tabActive, setTabActive] = useState('all');
    const [selectedRooms, setSelectedRooms] = useState([]);
    const [message, setMessage] = useState('');
    const currentUser = "AD"; // Định danh bạn là Admin

    const [chatHistory, setChatHistory] = useState(() => {
        const savedChat = localStorage.getItem('chatHistory');
        return savedChat ? JSON.parse(savedChat) : [];
    });

    const chatEndRef = useRef(null);

    const scrollToBottom = () => {
        chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        localStorage.setItem('chatHistory', JSON.stringify(chatHistory));
        scrollToBottom();
    }, [chatHistory, tabActive]);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const toggleRoom = (roomId) => {
        if (selectedRooms.includes(roomId)) {
            setSelectedRooms(selectedRooms.filter(id => id !== roomId));
        } else {
            setSelectedRooms([...selectedRooms, roomId]);
        }
    };

    const handleSendMessage = (type) => {
        if (message.trim() === '') return;

        const newMessage = {
            id: Date.now(),
            sender: currentUser,
            content: message,
            type: type, 
            target: type === 'all' ? 'Tất cả' : selectedRooms.join(', '),
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        setChatHistory([...chatHistory, newMessage]);
        setMessage('');
    };

    // Kiểm tra điều kiện gửi tin nhắn riêng
    const canSendPrivate = selectedRooms.length > 0 && message.trim() !== '';

    // Hàm render tin nhắn thông minh
    const renderMessageList = (type) => {
        const filteredChats = chatHistory.filter(m => m.type === type);

        return filteredChats.map((msg, index) => {
            const isMe = msg.sender === currentUser;
            const prevMsg = filteredChats[index - 1];
            const isSameSenderAsPrev = prevMsg && prevMsg.sender === msg.sender;

            return (
                <div key={msg.id} style={{ 
                    display: 'flex', 
                    flexDirection: 'column',
                    alignItems: isMe ? 'flex-end' : 'flex-start',
                    marginBottom: isSameSenderAsPrev ? '2px' : '12px',
                    marginTop: isSameSenderAsPrev ? '0px' : '8px'
                }}>
                    <div style={{ 
                        display: 'flex', 
                        flexDirection: isMe ? 'row-reverse' : 'row', 
                        alignItems: 'flex-end',
                        gap: '8px',
                        maxWidth: '85%'
                    }}>
                        {/* Avatar: Chỉ hiện ở tin nhắn cuối cùng của chuỗi hoặc nếu đứng một mình */}
                        <div style={{ width: '32px', flexShrink: 0 }}>
                            {!isSameSenderAsPrev && (
                                <div style={{ 
                                    width: '32px', height: '32px', borderRadius: '50%', 
                                    backgroundColor: isMe ? '#444' : '#222', color: '#fff', 
                                    display: 'flex', alignItems: 'center', justifyContent: 'center', 
                                    fontSize: '10px', fontWeight: 'bold' 
                                }}>
                                    {msg.sender}
                                </div>
                            )}
                        </div>

                        <div style={{ 
                            backgroundColor: isMe ? 'rgba(50, 50, 50, 0.9)' : 'rgba(255, 255, 255, 0.95)', 
                            padding: '10px 14px', 
                            borderRadius: isMe 
                                ? (isSameSenderAsPrev ? '18px 4px 18px 18px' : '18px 18px 4px 18px') 
                                : (isSameSenderAsPrev ? '4px 18px 18px 18px' : '18px 18px 18px 4px'), 
                            fontSize: '13px', 
                            color: isMe ? '#fff' : '#333',
                            boxShadow: '0 1px 2px rgba(0,0,0,0.1)',
                        }}>
                            {/* Hiện mục tiêu gửi nếu là tin nhắn riêng đầu tiên */}
                            {type === 'private' && isMe && !isSameSenderAsPrev && (
                                <div style={{ fontSize: '9px', opacity: 0.6, borderBottom: '1px solid rgba(255,255,255,0.2)', marginBottom: '4px' }}>
                                    Đến: {msg.target}
                                </div>
                            )}
                            {msg.content}
                            <div style={{ fontSize: '8px', opacity: 0.4, marginTop: '3px', textAlign: isMe ? 'right' : 'left' }}>
                                {msg.time}
                            </div>
                        </div>
                    </div>
                </div>
            );
        });
    };

    return (
        <div style={{
            flex: 1, display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', 
            borderRadius: '30px', overflow: 'hidden', height: 'calc(100vh - 120px)', minHeight: 0 
        }} className="glass-card">

            {/* Header: Tab Select */}
            <div style={{ padding: '20px', display: 'flex', gap: '15px', flexShrink: 0 }}>
                <button onClick={() => setTabActive('all')} style={{ padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold', backgroundColor: tabActive === 'all' ? '#333' : 'rgba(255,255,255,0.6)', color: tabActive === 'all' ? '#fff' : '#333', cursor: 'pointer' }}>
                    Nhắn tin chung
                </button>
                <button onClick={() => setTabActive('private')} style={{ padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold', backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'rgba(255,255,255,0.6)', color: tabActive === 'private' ? '#fff' : '#333', cursor: 'pointer' }}>
                    Nhắn tin riêng
                </button>
            </div>

            {/* Chat Body */}
            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', overflow: 'hidden', minHeight: 0 }}>
                {tabActive === 'all' ? (
                    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                        <div style={{ flex: 1, overflowY: 'auto', paddingRight: '10px' }} className="custom-scrollbar">
                            {renderMessageList('all')}
                            <div ref={chatEndRef} />
                        </div>

                        <div style={{ display: 'flex', gap: '10px', paddingTop: '15px', flexShrink: 0 }}>
                            <input style={{ flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none' }} placeholder="Gửi tin nhắn chung..." value={message} onChange={(e) => setMessage(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && handleSendMessage('all')} />
                            <button onClick={() => handleSendMessage('all')} style={{ padding: '0 30px', borderRadius: '15px', border: 'none', backgroundColor: '#333', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }}>Gửi</button>
                        </div>
                    </div>
                ) : (
                    <div style={{ flex: 1, display: 'flex', gap: '20px', minHeight: 0 }}>
                        <div style={{ width: '230px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '6px', alignContent: 'flex-start', overflowY: 'auto', paddingRight: '5px' }} className="custom-scrollbar">
                            {allRooms.map(room => (
                                <div key={room} onClick={() => toggleRoom(room)} style={{ background: selectedRooms.includes(room) ? '#8b5e5e' : 'white', color: selectedRooms.includes(room) ? 'white' : '#333', padding: '8px 0', borderRadius: '8px', textAlign: 'center', fontSize: '11px', fontWeight: 'bold', cursor: 'pointer', border: '1px solid #ddd' }}>{room}</div>
                            ))}
                        </div>

                        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', backgroundColor: 'rgba(255,255,255,0.1)', borderRadius: '20px', border: '1px solid rgba(255,255,255,0.2)', padding: '15px', minHeight: 0 }}>
                            <div style={{ flex: 1, overflowY: 'auto', paddingRight: '10px' }} className="custom-scrollbar">
                                <p style={{ color: '#fff', fontSize: '14px', fontWeight: 'bold', marginBottom: '10px' }}>Gửi đến: {selectedRooms.join(', ') || 'Chưa chọn'}</p>
                                {renderMessageList('private')}
                                <div ref={chatEndRef} />
                            </div>

                            <div style={{ display: 'flex', gap: '10px', marginTop: '10px', flexShrink: 0 }}>
                                <input style={{ flex: 1, padding: '15px', borderRadius: '15px', border: 'none', outline: 'none' }} placeholder="Nhắn riêng..." value={message} onChange={(e) => setMessage(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && canSendPrivate && handleSendMessage('private')} />
                                <button disabled={!canSendPrivate} onClick={() => handleSendMessage('private')} style={{ padding: '0 25px', borderRadius: '15px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', opacity: canSendPrivate ? 1 : 0.5, cursor: canSendPrivate ? 'pointer' : 'not-allowed' }}>Gửi</button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
            `}</style>
        </div>
    );
};

export default NhanTin;
